ning ? { warning: info.warning } : {}),\n    }\n    if (profiled.profile !== 'vite') return base\n    if (process.platform === 'win32' && info.packageManager === 'pnpm' && Number(info.packageManagerVersion?.split('.')[0]) >= 12) {\n      return { ...base, supported: false, reason: '项目声明的 pnpm 12+ 在 Windows 上需要写入系统存储锁目录，当前宿主沙箱尚不支持；不会自动换版本或放宽权限。可试跑内置示例，需求草稿会保留。' }\n    }\n    try { projectCommandArgv([info.packageManager, '--version'], dir, process.platform, { pnpm: bundledPnpm() }) }\n    catch { return { ...base, supported: false, reason: `未找到项目需要的 ${info.packageManager}。请在 DSH 所用环境中安装或启用该包管理器；需求草稿会保留。` } }\n    return base\n  }\n  const label = (v: unknown): CandidateLabel | undefined => ((CANDIDATE_LABELS as readonly unknown[]).includes(v) ? v as CandidateLabel : undefined)\n  const resolveConversation = conversationResolver({ attached: () => agents?.list() ?? [], controller: () => ctx.get('sessionController') as SessionController<AgentLike> | undefined, guard })\n  const agentFor = (b: Record<string, unknown>, signal: AbortSignal): Promise<AgentLike> => resolveConversation(b.sessionId, signal)\n  const view = async (runId: string): Promise<unknown> => {\n    const r = await comparer.observe(runId)\n    if (r === undefined) throw new HttpError(404, 'unknown run')\n    return present(r)\n  }\n  const routeOf = (v: unknown): AgentRoute | undefined => {\n    if (v === null || typeof v !== 'object') return undefined\n    const o = v as Record<string, unknown>\n    return typeof o.model === 'string' && o.model !== '' ? { ...(typeof o.provider === 'string' ? { provider: o.provider } : {}), model: o.model } : undefined\n  }\n  const api: Record<string, Handler> = {\n    async preferences(b, signal) {\n      const agent = await agentFor(b, signal)\n      return b.value === undefined ? preferences.load(agent.session.id) : preferences.save(agent.session.id, b.value)\n    },\n    async setup(b, signal) {\n      const agent = await agentFor(b, signal)\n      const project = await describeProject(agent.session.header.cwd)\n      return { hostVersion: VERSION, pluginVersion: VERSION, dshVersion: await runtimeVersion, projectProcess: { platform: process.platform, windowsCompatControl: true }, features: { currentComparisonContext: 'scoped-assembly-v1' }, capabilities: await capabilities(), current: currentRoute(agent), project, generationMinutes: config.generationMinutes ?? DEFAULT_GENERATION_MS / 60_000 }\n    },\n    async list(b) {\n      const page = await historyPage(store, b)\n      return { ...page, runs: await Promise.all(page.runs.map(present)), isolation: runner.isolation }\n    },\n    /** Recent visible conversation entries the user can tick for both candidates. */\n    async contextEntries(b, signal) {\n      const agent = await agentFor(b, signal)\n      return { entries: listedEntries(agent.session.snapshotEvents(0)), limits: { messageChars: MESSAGE_CHARS, totalChars: CONTEXT_CHARS } }\n    },\n    /** Exactly what a submission with these settings would give both candidates. */\n    async contextPreview(b, signal) {\n      const agent = await agentFor(b, signal)\n      // The settings being edited may not be saved yet; the request states them explicitly.\n      const stored = await preferences.load(agent.session.id)\n      let saved: typeof stored\n      try { saved = parsePreferences({ ...stored, ...(b.mode === undefined ? {} : { contextMode: b.mode }), ...(b.turns === undefined ? {} : { contextTurns: b.turns }) }) }\n      catch (error) { throw new HttpError(400, (error as Error).message) }\n      const ids = Array.isArray(b.ids) && b.ids.length <= 200 && b.ids.every(id => Number.isSafeInteger(id) && (id as number) >= 0) ? b.ids as number[] : undefined\n      if (b.ids !== undefined && ids === undefined) throw new HttpError(400, '所选主对话消息无效')\n      return buildConversationContext(agent.session.snapshotEvents(0), contextRequestOf(saved, ids), await pendingNotes(agent.session)) ?? null\n    },\n    async latest(b) {\n      if