p.name).join('、')}；可以返回同一模型模式或稍后重试。`)\n        return { current: currentRoute(agent), models: catalog.groups.flatMap(p => p.models.map(m => ({ provider: p.id, providerName: p.name, id: m.id, name: m.name }))) }\n      }\n      const llm = (agent.ctx.get('llm') ?? ctx.get('llm')) as LlmService | undefined\n      const models: Array<{ provider: string; providerName: string; id: string; name: string }> = []\n      for (const p of llm?.listProviders() ?? []) {\n        const listed = await llm!.listModels(p.id)\n        for (const m of listed) models.push({ provider: p.id, providerName: p.name ?? p.id, id: m.id, name: m.name })\n      }\n      return { current: currentRoute(agent), models }\n    },\n    async start(b, signal) {\n      const agent = await agentFor(b, signal)\n      const task = typeof b.task === 'string' ? b.task : ''\n      const mode = b.mode === 'cross-model' ? 'cross-model' : 'same-model'\n      const listed = Array.isArray(b.models) ? b.models.map(routeOf) : []\n      if (mode === 'cross-model' && (listed.length < 2 || listed.length > 4 || listed.some(route => route === undefined))) throw new HttpError(400, '请为每一版选择一个模型')\n      const versions = b.versions === undefined ? undefined : Number(b.versions)\n      const follows = typeof b.follows === 'string' && /^[0-9a-f]{8}$/.test(b.follows) ? b.follows : undefined\n      if (b.generationMinutes !== undefined && (typeof b.generationMinutes !== 'number' || !Number.isFinite(b.generationMinutes) || b.generationMinutes < 5 || b.generationMinutes > 120)) throw new HttpError(400, '每版生成上限需要在 5 到 120 分钟之间')\n      const minutes = b.generationMinutes as number | undefined\n      const saved = await preferences.load(agent.session.id)\n      const windowsProcessCompat = b.windowsProcessCompat ?? saved.windowsProcessCompat ?? 'auto'\n      if (windowsProcessCompat !== 'auto' && windowsProcessCompat !== 'off') throw new HttpError(400, 'Windows 进程兼容设置无效')\n      if (b.exampleKind !== undefined && b.exampleKind !== 'quick' && b.exampleKind !== 'full') throw new HttpError(400, '示例类型无效')\n      const exampleKind = b.exampleKind === 'full' ? 'full' : 'quick'\n      let plan: ComparisonPlan\n      try { plan = comparisonPlan(saved, currentRoute(agent), { mode, ...(mode === 'cross-model' ? { models: listed as AgentRoute[] } : {}), ...(versions === undefined ? {} : { versions }) }) }\n      catch (error) { throw new HttpError(400, (error as Error).message) }\n      const repo = b.example === true ? await createExampleRepo(store.examplesDir, undefined, exampleKind) : await repoFor(agent, signal)\n      const r = await comparer.start({\n        repo,\n        task: b.example === true && task.trim() === '' ? exampleTask(exampleKind) : task,\n        ...plan,\n        hostContext: agent,\n        sessionId: agent.session.id,\n        ...(follows === undefined ? {} : { follows }),\n        origin: { kind: 'panel' },\n        windowsProcessCompat,\n        ...(minutes === undefined ? {} : { generationMs: minutes * 60_000 }),\n      })\n      return present(r)\n    },\n    async reopenPreview(b) {\n      const l = label(b.label)\n      if (l === undefined) throw new HttpError(400, 'label must be A, B, C or D')\n      return present(await comparer.reopenPreview(runIdOf(b), l))\n    },\n    async salvage(b) {\n      const l = label(b.label)\n      if (l === undefined) throw new HttpError(400, 'label must be A, B, C or D')\n      return present(await comparer.salvage(runIdOf(b), l))\n    },\n    async retryVerification(b) {\n      const l = label(b.label)\n      if (l === undefined) throw new HttpError(400, 'label must be A, B, C or D')\n      return present(await comparer.retryVerification(runIdOf(b), l))\n    },\n    async choose(b) {\n      const pick = b.pick === 'none' ? 'none' : label(b.pick)\n      if (pick === undefined) throw new HttpError(400, 'pick must be a candidate label or none')\n      return present(await comparer.choose(runIdOf(b), pick, typeof b.note === 'string' ? b.note.slice(0, 500) : undefined))\n    },\n    /** Why the pick won: known reasons and a short note. The next step of the conversation hears it. */\n    async explain(b) {\n      if (!(CANDIDATE_LABELS as readonly unknown[]).includes(b.pick)) throw new HttpError(400, 'pick must name the version being explained')\n      const reasons = Array.isArray(b.reasons) ? b.reasons : []\n      if (reasons.length > PICK_REASONS.length || reasons.some(reason => !(PICK_REASONS as readonly unknown[]).includes(reason))) throw new HttpError(400, 'reasons must be known pick reasons')\n      if (b.note !== undefined && typeof b.note !== 'string') throw new HttpError(400, 'note must be text')\n      return present(await comparer.explainChoice(runIdOf(b), reasons as PickReason[], typeof b.note === 'string' ? b.note : undefined, b.pick as CandidateLabel))\n    },\n    async preflight(b) { return { ...await comparer.adoptPreflight(runIdOf(b)), protectedWorktreeApply: true } },\n    async adopt(b) { return present(await comparer.adopt(runIdOf(b), b.mode === 'branch' ? 'branch' : b.mode === 'folder' ? 'folder' : 'worktree')) },\n    /**\n     * Turn the conversation's folder into a Git repository so both versions\n     * start from its files. `check: true` only reports whether it may.\n     */\n    async enableGit(b, signal) {\n      const agent = await agentFor(b, signal)\n      const cwd = agent.session.header.cwd\n      if (!cwd) throw new HttpError(400, '这条对话没有目录')\n      if (b.check === true) return checkEnableGit(cwd)\n      try { await enableGit(cwd) }\n      catch (error) { throw new HttpError(409, (error as Error).message) }\n      return describeProject(cwd)\n    },\n    /** One file a version wrote. Before the reveal only results judged by their files can be read. */\n    async candidateFile(b) {\n      const r = await comparer.get(runIdOf(b))\n      const c = r?.candidates.find((x) => x.label === label(b.label))\n      if (r === undefined || c === undefined) throw new HttpError(404, '没有这个候选')\n      if (!identitiesShown(r) && c.result !== 'files') throw new HttpError(403, '选择之后才能查看改动')\n      if (typeof b.path !== 'string' || !(c.touchedFiles ?? []).includes(b.path)) throw new HttpError(404, '这一版没有写这个文件')\n      return comparer.readResultFile(r.runId, c.label, b.path)\n    },\n    async cancelAdoption(b, signal) {\n      const runId = runIdOf(b), record = await comparer.get(runId)\n      if (!record) throw new HttpError(404, '没有这次比较')\n      return present(await comparer.cancelAdoption(runId))\n    },\n    async revert(b) { return present(await comparer.revert(runIdOf(b))) },\n    async recover(b) { return present(await comparer.recoverAdoption(runIdOf(b), b.action === 'keep' ? 'keep' : 'restore')) },\n    async cancel(b) { const r = await comparer.cancel(runIdOf(b), label(b.label)); return r === undefined ? null : present(r) },\n    async cleanup(b, signal) { return api.releaseCopies!(b, signal) },\n    async copyCleanupPlan(b, signal) {\n      const agent = await agentFor(b, signal)\n      const runId = runIdOf(b), record = await comparer.get(runId)\n      if (!record) throw new HttpError(404, '没有这次比较')\n      return { ...await comparer.copyCleanupPlan(runId, signal), otherSession: !record.sessionId || record.sessionId !== agent.session.id }\n    },\n    async releaseCopies(b, signal) {\n      const agent = await agentFor(b, signal)\n      const runId = runIdOf(b), record = await comparer.get(runId)\n      if (!record) throw new HttpError(404, '没有这次比较')\n      if (record.sessionId && record.sessionId !== agent.session.id && b.confirmOtherSession !== true) throw new HttpError(409, '这次比较属于另一个对话，请明确确认后再释放副本。')\n      if (typeof b.token !== 'string') throw new HttpError(400, '请先查看本次副本清单')\n      return present(await comparer.releaseCopies(runId, b.token))\n    },\n    async shot(b) {\n      const r = await comparer.get(runIdOf(b))\n      const c = r?.candidates.find((x) => x.label === label(b.label))\n      const file = b.mobile === true ? c?.mobileScreenshot : c?.screenshot\n      if (file === undefined) throw new HttpError(404, 'no screenshot')\n      return { dataUrl: `data:image/png;base64,${(await readFile(file)).toString('base64')}` }\n    },\n    async patch(b) {\n      const r = await comparer.get(runIdOf(b))\n      const c = r?.candidates.find((x) => x.label === label(b.label))\n      if (r === undefined || c?.patchFile === undefined) throw new HttpError(404, 'no patch')\n      // An open comparison shows every change from the start; a blind one after the pick.\n      if (!identitiesShown(r)) throw new HttpError(403, '选择之后才能查看改动')\n      const text = await readFile(c.patchFile, 'utf8')\n      return { sha256: c.patchSha256, truncated: text.length > 400_000, text: text.slice(0, 400_000) }\n    },\n  }\n\n  assertComparisonActionRoutes(api)\n\n  ctx.inject(['webServer', 'connection'], (web) => web.effect(() => web.webServer.register({\n    kind: 'prefix',\n    path: ROUTE,\n    handler: async (req, res) => {\n      if (web.connection.requestRejection(req) !== undefined) return json(res, 403, { ok: false, error: 'forbidden' })\n      if (req.method !== 'POST') return json(res, 405, { ok: false, error: 'method not allowed' })\n      const method = new URL(req.url ?? '/', 'http://dsh.internal').pathname.slice(ROUTE.length + 1)\n      const handler = Object.hasOwn(api, method) ? api[method] : undefined\n      if (handler === undefined) return json(res, 404, { ok: false, error: `unknown method ${method}` })\n      const ctl = new AbortController()\n      res.once('close', () => { if (!res.writableEnded) ctl.abort() })\n      try {\n        const body = await readBody(req)\n        const value = await dispatchComparisonAction({ method, comparer, caller: () => agentFor(body, ctl.signal), runId: () => runIdOf(body), confirmation: body.confirmOtherSession, signal: ctl.signal }, () => handler(body, ctl.signal))\n        json(res, 200, { ok: true, value })\n      } catch (error) {\n        const status = error instanceof HttpError || error instanceof SessionAccessError ? error.status : error instanceof HistoryQueryError ? 400 : error instanceof RecordUnavailableError || error instanceof ChoiceChangedError || (error as Error).name === 'BusyError' ? 409 : 500\n        json(res, status, { ok: false, error: (error as Error).message, ...(error instanceof HttpError && error.code ? { code: error.code } : {}) })\n      }\n    },\n  }), 'agent-compare: /agent-compare/api routes'))\n}\n\n/** The settings strip's description of a conversation's directory (see `describeProject`). */\ninterface ProjectDescription {\n  readonly path: string\n  readonly supported: boolean\n  readonly workspace: 'repository' | 'folder'\n  readonly profile?: ProjectProfile\n  readonly projectPath?: string\n  readonly reason?: string\n  readonly warning?: string\n  /** `node-web`: the server script both versions are shown with. */\n  readonly script?: 'dev' | 'start'\n  /** Why the project's package.json cannot be used this time (no install). */\n  readonly packageNote?: string\n  /** A folder outside Git that may become a repository, so both versions start from its files. */\n  readonly canEnableGit?: boolean\n}\n\n/** Whether `child` is `parent` or below it, compared the way the platform compares paths. */\nexport function insideDirectory(parent: string, child: string | undefined): boolean {\n  if (!child) return false\n  const fold = (value: string): string => process.platform === 'win32' ? path.resolve(value).toLowerCase() : path.resolve(value)\n  const relative = path.relative(fold(parent), fold(child))\n  return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative))\n}\n\nfunction json(res: ServerResponse, status: number, body: unknown): void {\n  if (res.headersSent) return\n  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n  res.end(JSON.stringify(body))\n}\n\n"
